<?php
namespace App\Service\HelloAsso;
use Symfony\Component\HttpFoundation\IpUtils;use Symfony\Component\HttpFoundation\Request;
final readonly class HelloAssoWebhookAuthenticator{public function __construct(private string $secret,private string $allowedIps,private bool $allowUnsigned,private string $environment){}public function isAuthenticated(Request $request,string $raw):bool{$hasConfiguredMethod=false;$signature=(string)$request->headers->get('x-ha-signature','');if($this->secret!==''&&$signature!==''){$hasConfiguredMethod=true;$expected=hash_hmac('sha256',$raw,$this->secret);if(hash_equals(strtolower($expected),strtolower($signature)))return true;return false;} $ips=array_values(array_filter(array_map('trim',explode(',',$this->allowedIps)),static fn(string $ip):bool=>$ip!==''));if($ips!==[]){$hasConfiguredMethod=true;$clientIp=$request->getClientIp();if($clientIp!==null&&IpUtils::checkIp($clientIp,$ips))return true;}if($this->allowUnsigned&&$this->environment!=='prod')return true;return !$hasConfiguredMethod&&false;}}
